&lt;/div&gt;
&lt;ul class=&quot;public-DraftStyleDefault-ul&quot; data-offset-key=&quot;ajklo-0-0&quot;&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;653s3&quot; data-offset-key=&quot;ajklo-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;ajklo-0-0&quot;&gt;&lt;span data-offset-key=&quot;ajklo-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Master’s, or Ph.D. in Electrical Engineering, Computer Science, Mathematics, Physics, or a related field, with 3+ years of relevant experience.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;653s3&quot; data-offset-key=&quot;4i2g5-0-0&quot;&gt;
